[CmdletBinding()]
param([switch]$PreflightSelfTest)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$id = (Get-Date).ToUniversalTime().ToString('yyyyMMddHHmmssfff')
$schema = "wp54_$id"; $marker = "wp54:$id"
$temp = [IO.Path]::GetTempPath(); $snapshot = Join-Path $temp "CelebrateDeal-WP54-$id"; $runtime = Join-Path $temp "CelebrateDeal-WP54-runtime-$id"
$report = Join-Path $root ".ai-team\reports\wp-54-accountant-form-edit-direct-url-$id"
$receipts = [Collections.Generic.List[object]]::new(); $failure = $null; $schemaCreated = $false; $baseline = $null

function Safe([string]$v) { if ($null -eq $v) { return '' }; $r=$v -replace '(?i)postgres(?:ql)?://\S+','[REDACTED_DATABASE_URL]'; $r=$r -replace '(?i)(token|secret|password|authorization)\s*[:=]\s*[^\s,;]+','$1=[REDACTED]'; return $r -replace '(?i)[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}','[REDACTED_EMAIL]' }
function Json([string]$n,$v) { $v|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $report $n) -Encoding UTF8 }
function Receipt([string]$n,[int]$x,[long]$ms,[string]$o,[string]$e) { $s=Safe (($o+"`n"+$e).Trim()); if($s.Length -gt 3500){$s=$s.Substring(0,3500)}; $receipts.Add([ordered]@{name=$n;exit_code=$x;duration_ms=$ms;classification=if($x-eq 0){'PASS'}else{'FAIL'};sanitized_summary=$s})|Out-Null }
function Invoke-Child([string]$n,[string]$file,[string[]]$arguments,[Collections.IDictionary]$environment) { $i=[Diagnostics.ProcessStartInfo]::new();$i.FileName=$file;$i.Arguments=$arguments -join ' ';$i.WorkingDirectory=$snapshot;$i.UseShellExecute=$false;$i.RedirectStandardOutput=$true;$i.RedirectStandardError=$true;$i.CreateNoWindow=$true;$i.Environment.Clear();foreach($k in $environment.Keys){$i.Environment[$k]=[string]$environment[$k]};$p=[Diagnostics.Process]::new();$p.StartInfo=$i;$w=[Diagnostics.Stopwatch]::StartNew();[void]$p.Start();$o=$p.StandardOutput.ReadToEndAsync();$e=$p.StandardError.ReadToEndAsync();$p.WaitForExit();$w.Stop();$out=$o.GetAwaiter().GetResult();$err=$e.GetAwaiter().GetResult();Receipt $n $p.ExitCode $w.ElapsedMilliseconds $out $err;return $p.ExitCode }
function Env { $url="postgresql://postgres:postgres@127.0.0.1:54329/celebratedeal_ci?schema=$schema"; return [ordered]@{PATH=$env:PATH;SystemRoot=$env:SystemRoot;ComSpec=$env:ComSpec;PATHEXT=$env:PATHEXT;NODE_ENV='test';CI='true';DATABASE_URL=$url;DIRECT_URL=$url;E2E_PORT='31054';E2E_BASE_URL='http://127.0.0.1:31054';E2E_SMOKE_TEST_EMAIL='wp54-synthetic@celebratedeal.test';RATE_LIMIT_PROVIDER='memory';PAYMENT_PROVIDER='demo';JOB_SECRET='wp54-job-secret-at-least-16-chars';CSRF_SECRET='wp54-csrf-secret-at-least-16-chars';SENTRY_DSN='';NEXT_PUBLIC_SENTRY_DSN='';SENTRY_AUTH_TOKEN='';RESEND_API_KEY='';EMAIL_FROM='';SENTRY_DISABLE_AUTO_UPLOAD='true';PLAYWRIGHT_BROWSERS_PATH=(Join-Path ([Environment]::GetFolderPath([Environment+SpecialFolder]::LocalApplicationData)) 'ms-playwright');PLAYWRIGHT_JSON_OUTPUT_FILE=(Join-Path $snapshot '.wp54-browser.json');TEMP=(Join-Path $runtime 'temp');TMP=(Join-Path $runtime 'tmp');HOME=(Join-Path $runtime 'home');USERPROFILE=(Join-Path $runtime 'home');NPM_CONFIG_CACHE=(Join-Path $runtime 'npm-cache')} }
function Preflight { if($schema -notmatch '^wp54_[a-z0-9_]+$'){throw 'Invalid schema.'};if(@(git -C $root diff --cached --name-only).Count -ne 0){throw 'Staged index must be empty.'};$s=@(git -C $root status --short);$own=@('?? .ai-team/scripts/Invoke-Wp54AccountantFormEditDirectUrlQa.ps1','?? tests/e2e/accountant-form-edit-direct-url.spec.ts');if(@($s|Where-Object{$_ -in $own}).Count-ne 2){throw 'WP-54 owned paths missing.'};if(-not(Test-NetConnection -ComputerName '127.0.0.1' -Port 54329 -InformationLevel Quiet)){throw 'Local disposable DB unavailable.'};foreach($g in @(@('src/app/(app)/forms/[id]/edit/page.tsx','requireVendorManager'),@('src/lib/auth.ts','/dashboard?error=insufficient_role'))){if(-not(Select-String -LiteralPath $g[0] -Pattern $g[1] -SimpleMatch -Quiet)){throw 'Source contract drift.'}};return $s }
if($PreflightSelfTest){$null=Preflight;Write-Output 'WP-54 preflight PASS';exit 0}
try { $baseline=Preflight;New-Item -ItemType Directory -Force -Path $report,$snapshot,$runtime|Out-Null;$excluded=@('.git','.ai-team','.next','node_modules','test-results');Get-ChildItem -LiteralPath $root -Force|Where-Object{$_.Name-notin $excluded -and $_.Name-notlike '.env*'}|ForEach-Object{Copy-Item -LiteralPath $_.FullName -Destination $snapshot -Recurse -Force};New-Item -ItemType Junction -Path (Join-Path $snapshot 'node_modules') -Target (Join-Path $root 'node_modules')|Out-Null;$cfg=Join-Path $snapshot 'playwright.config.ts';$txt=[IO.File]::ReadAllText($cfg);$txt=$txt.Replace('npx prisma generate && npx next build && npx next start --port ${port}','npx next build --webpack && npx next start --port ${port}').Replace('timeout: 120_000','timeout: 300_000');[IO.File]::WriteAllText($cfg,$txt,[Text.UTF8Encoding]::new($false));$run=Env;New-Item -ItemType Directory -Force -Path $run.TEMP,$run.TMP,$run.HOME,$run.NPM_CONFIG_CACHE|Out-Null;$node=(Get-Command node.exe).Source;$prisma='node_modules/prisma/build/index.js';if((Invoke-Child 'prisma-validate' $node @($prisma,'validate') $run)-ne 0){throw 'Prisma validation failed.'};$boot=Join-Path $snapshot 'wp54-bootstrap.sql';[IO.File]::WriteAllText($boot,"CREATE SCHEMA IF NOT EXISTS `"$schema`";`nCOMMENT ON SCHEMA `"$schema`" IS '$marker';",[Text.UTF8Encoding]::new($false));if((Invoke-Child 'database-bootstrap' $node @($prisma,'db','execute','--schema','prisma/schema.prisma','--file','.\wp54-bootstrap.sql') $run)-ne 0){throw 'Bootstrap failed.'};$schemaCreated=$true;if((Invoke-Child 'migrate-deploy' $node @($prisma,'migrate','deploy') $run)-ne 0){throw 'Migrate failed.'};if((Invoke-Child 'migrate-status' $node @($prisma,'migrate','status') $run)-ne 0){throw 'Migrate status failed.'};if((Invoke-Child 'spec-eslint' $node @('node_modules/eslint/bin/eslint.js','tests/e2e/accountant-form-edit-direct-url.spec.ts') $run)-ne 0){throw 'Lint failed.'};if((Invoke-Child 'auth-unit' $node @('node_modules/vitest/vitest.mjs','run','src/lib/auth.test.ts') $run)-ne 0){throw 'Auth tests failed.'};if((Invoke-Child 'browser-e2e' $node @('node_modules/@playwright/test/cli.js','test','tests/e2e/accountant-form-edit-direct-url.spec.ts','--project=chromium','--retries=0','--reporter=json') $run)-ne 0){throw 'Browser gate failed.'};if((Invoke-Child 'typecheck' $node @('node_modules/typescript/bin/tsc','--noEmit') $run)-ne 0){throw 'Typecheck failed.'};$b=Get-Content -LiteralPath $run.PLAYWRIGHT_JSON_OUTPUT_FILE -Raw|ConvertFrom-Json;$verdict=[ordered]@{artifactType='browser-verdict';expected=[int]$b.stats.expected;unexpected=[int]$b.stats.unexpected;skipped=[int]$b.stats.skipped;flaky=[int]$b.stats.flaky;pass=($b.stats.expected-eq 1 -and $b.stats.unexpected-eq 0 -and $b.stats.skipped-eq 0 -and $b.stats.flaky-eq 0)};Json 'browser-verdict.sanitized.json' $verdict;if(-not $verdict.pass){throw 'Browser verdict failed.'};Json 'db-invariant-summary.sanitized.json' ([ordered]@{artifactType='db-invariant';assertion='Spec compares full form row and vendor form count before/after denied direct URL.';result='UNCHANGED'}) } catch {$failure=Safe $_.Exception.Message} finally { if($schemaCreated){try{$run=Env;$clean=Join-Path $snapshot 'wp54-cleanup.sql';$sql='DO $$ BEGIN IF current_database() <> ''celebratedeal_ci'' THEN RAISE EXCEPTION ''database mismatch''; END IF; IF (SELECT obj_description(oid, ''pg_namespace'') FROM pg_namespace WHERE nspname = '''+$schema+''') <> '''+$marker+''' THEN RAISE EXCEPTION ''marker mismatch''; END IF; EXECUTE ''DROP SCHEMA "'+$schema+'" CASCADE''; END $$;';[IO.File]::WriteAllText($clean,$sql,[Text.UTF8Encoding]::new($false));$x=Invoke-Child 'database-cleanup' $node @($prisma,'db','execute','--schema','prisma/schema.prisma','--file','.\wp54-cleanup.sql') $run;if($x-ne 0){throw 'Schema cleanup failed.'}}catch{if($null-eq $failure){$failure=Safe $_.Exception.Message}}};$post=@(git -C $root status --short);$summary=[ordered]@{artifactType='final-runner-summary';workPackage='WP-54';runId=$id;finalRunnerError=$failure;syntheticEnvironmentOnly=$true;preflightStatus=$baseline;postflightStatus=$post;schemaCleanup=if($schemaCreated){'ATTEMPTED'}else{'NOT_CREATED'}};Json 'final-runner-summary.sanitized.json' $summary;Json 'command-receipts.sanitized.json' ([ordered]@{artifactType='command-receipts';workPackage='WP-54';receipts=@($receipts)});if(Test-Path $snapshot){Remove-Item -LiteralPath $snapshot -Recurse -Force};if(Test-Path $runtime){Remove-Item -LiteralPath $runtime -Recurse -Force} }
Write-Output "WP-54 report: $report";if($failure){throw $failure}
